$key = (Get-Content (Join-Path $env:USERPROFILE '.dsh-qq\keys\agnes.txt') -Raw).Trim()
$img = 'https://raw.githubusercontent.com/HRuiCcc/RuiC-PoseAtlas/main/img/full_sexy_P001_front.png'
$body = @{ model='agnes-image-2.5-flash'; prompt='a young woman standing in exactly this pose, full body, studio light, photorealistic'; n=1; size='1024x1024'; image=$img } | ConvertTo-Json -Compress
try {
  $r = Invoke-RestMethod -Uri 'https://apihub.agnes-ai.com/v1/images/generations' -Method Post -Headers @{ Authorization = "Bearer $key" } -ContentType 'application/json; charset=utf-8' -Body ([Text.Encoding]::UTF8.GetBytes($body)) -TimeoutSec 120
  $j = $r | ConvertTo-Json -Depth 4
  $j.Substring(0, [Math]::Min(600, $j.Length))
} catch {
  $resp = $_.Exception.Response
  if ($resp) { "HTTP " + [int]$resp.StatusCode; $sr = New-Object IO.StreamReader($resp.GetResponseStream()); "body: " + $sr.ReadToEnd() } else { 'ERR ' + $_.Exception.Message }
}", "description": "试生图接口带参考图", "timeoutMs": 180000}

