{"command": "$OutputEncoding=[System.Text.UTF8Encoding]::new($false); [Console]::OutputEncoding=[System.Text.UTF8Encoding]::new($false)
$q = '古月方源 蛊真人 立绘'
$u = 'https://www.bing.com/images/search?q=' + [uri]::EscapeDataString($q) + '&form=HDRSC2&first=1'
try {
  $r = Invoke-WebRequest -Uri $u -Headers @{ 'User-Agent' = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/131.0 Safari/537.36' } -TimeoutSec 40
  $ms = [regex]::Matches($r.Content, 'murl&quot;:&quot;(.*?)&quot;')
  "count=" + $ms.Count
  $ms | Select-Object -First 12 | ForEach-Object { $_.Groups[1].Value }
} catch { 'ERR ' + $_.Exception.Message }", "description": "搜古月方源的图", "timeoutMs": 90000}

