{"command": "$OutputEncoding=[System.Text.UTF8Encoding]::new($false); [Console]::OutputEncoding=[System.Text.UTF8Encoding]::new($false)
$key = (Get-Content (Join-Path $env:USERPROFILE '.dsh-qq\keys\agnes.txt') -Raw).Trim()
$img = (Join-Path $env:USERPROFILE '.dsh-qq\media\refs\gzr\g14.jpg')
$b64 = [Convert]::ToBase64String([IO.File]::ReadAllBytes($img))
$body = @{ model='agnes-image-2.5-flash'; prompt='character design sheet, three views: front, side, back, full body, same character, long straight black hair, pale skin, white robe over black clothes, cold elegant face, narrow eyes, ink wash comic style, plain white background'; n=1; size='1024x1024'; image=('data:image/jpeg;base64,' + $b64) } | ConvertTo-Json -Compress
try {
  $r = Invoke-RestMethod -Uri 'https://apihub.agnes-ai.com/v1/images/generations' -Method Post -Headers @{ Authorization = "Bearer $key" } -ContentType 'application/json; charset=utf-8' -Body ([Text.Encoding]::UTF8.GetBytes($body)) -TimeoutSec 180
  ($r.data[0].url)
} catch {
  $resp = $_.Exception.Response
  if ($resp) { "HTTP " + [int]$resp.StatusCode; $sr = New-Object IO.StreamReader($resp.GetResponseStream()); "body: " + $sr.ReadToEnd() } else { 'ERR ' + $_.Exception.Message }
}", "description": "试本地图 base64 当参考", "timeoutMs": 200000}

