{"command": "$OutputEncoding=[System.Text.UTF8Encoding]::new($false); [Console]::OutputEncoding=[System.Text.UTF8Encoding]::new($false)
$key = (Get-Content (Join-Path $env:USERPROFILE '.dsh-qq\keys\agnes.txt') -Raw).Trim()
$img = (Join-Path $env:USERPROFILE '.dsh-qq\media\refs\gzr\g14.jpg')
$b64 = [Convert]::ToBase64String([IO.File]::ReadAllBytes($img))
$prompt = 'character reference details sheet, close-up face portrait, half body, hand detail, fabric fold detail, color palette swatches at the corner, same character: long straight black hair, pale skin, white outer robe with black inner garment, narrow cold eyes, ink comic style, clean white background'
$body = @{ model='agnes-image-2.5-flash'; prompt=$prompt; n=1; size='1024x1024'; image=('data:image/jpeg;base64,' + $b64) } | ConvertTo-Json -Compress
try {
  $r = Invoke-RestMethod -Uri 'https://apihub.agnes-ai.com/v1/images/generations' -Method Post -Headers @{ Authorization = "Bearer $key" } -ContentType 'application/json; charset=utf-8' -Body ([Text.Encoding]::UTF8.GetBytes($body)) -TimeoutSec 180
  $u = $r.data[0].url
  $o = Join-Path $env:USERPROFILE '.dsh-qq\media\agnes\fangyuan-detail-v1.png'
  Invoke-WebRequest -Uri $u -OutFile $o -UseBasicParsing -TimeoutSec 60
  "$o " + (Get-Item $o).Length
} catch {
  $resp = $_.Exception.Response
  if ($resp) { "HTTP " + [int]$resp.StatusCode } else { 'ERR ' + $_.Exception.Message }
}", "description": "画细节图", "timeoutMs": 200000}

