  (Join-Path $env:APPDATA 'NapCatQQ'),
  (Join-Path $env:USERPROFILE 'NapCatQQ'),
  (Join-Path $env:USERPROFILE '.dsh-qq\NapCat')
)
foreach ($p in $paths) { if (Test-Path $p) { "== $p"; Get-ChildItem $p -Recurse -File -Include *.json,*.yml,*.yaml -ErrorAction SilentlyContinue | Select-Object -First 15 | ForEach-Object { "   " + $_.FullName } } }
"--- 找 napcat 进程路径"
Get-Process | Where-Object { $_.ProcessName -match 'NapCat|QQ' } | Select-Object -First 3 | ForEach-Object { $_.Path }

